create or replace function public.net__blocked(p_x uuid, p_y uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.net_blocks k
                 where (k.blocker = p_x and k.blocked = p_y) or (k.blocker = p_y and k.blocked = p_x))
$$;

create or replace function public.net__met(p_x uuid, p_y uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.net_connections c
                 where c.a = least(p_x, p_y) and c.b = greatest(p_x, p_y) and c.removed_at is null)
$$;

create or replace function public.net__granted(p_owner uuid, p_viewer uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.net_contact_grants g
                 where g.owner = p_owner and g.viewer = p_viewer and g.revoked_at is null)
$$;

create or replace function public.net__is_person(p_id uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.net_people p where p.user_id = p_id)
$$;

-- Relationship of viewer v to owner o: self | blocked | accepted | met | stranger
create or replace function public.net__relation(p_v uuid, p_o uuid)
returns text language plpgsql stable security definer set search_path = '' as $$
begin
  if p_v = p_o then return 'self'; end if;
  if public.net__blocked(p_v, p_o) then return 'blocked'; end if;
  if public.net__granted(p_o, p_v) then return 'accepted'; end if;
  if public.net__met(p_v, p_o) then return 'met'; end if;
  return 'stranger';
end $$;

-- Block, then scope. p_via_card: a physical tap or scan of the owner's active card passes scope, never a block.
create or replace function public.net__can_see(p_v uuid, p_o uuid, p_via_card boolean default false)
returns boolean language plpgsql stable security definer set search_path = '' as $$
declare
  rel text;
  scope text;
  v_presenter boolean;
  v_registered boolean;
begin
  if p_v is null or p_o is null then return false; end if;
  if not public.net__is_person(p_o) then return false; end if;
  rel := public.net__relation(p_v, p_o);
  if rel = 'self' then return true; end if;
  if rel = 'blocked' then return false; end if;
  if p_via_card then return true; end if;
  if rel in ('met', 'accepted') then return true; end if;
  select coalesce((select e.visibility_scope from public.net_profile_ext e where e.user_id = p_o), 'presenters') into scope;
  select coalesce(bool_or(p.is_presenter), false), coalesce(bool_or(p.is_registered), false)
    into v_presenter, v_registered
    from public.net_people p where p.user_id = p_v;
  if scope = 'presenters' then return v_presenter; end if;
  if scope = 'all' then return v_registered; end if;
  return false; -- 'met'
end $$;

create or replace function public.net__themes_json(p_user uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'slug', t.slug, 'label', t.label, 'colour', t.colour, 'rank', pt.rank)
                            order by pt.rank), '[]'::jsonb)
  from public.net_profile_themes pt join public.net_themes t on t.id = pt.theme_id
  where pt.user_id = p_user
$$;

-- Field rules. p_level: self | tap | directory | met | accepted | second
--   tap        stranger who tapped or scanned the owner's card
--   directory  in-scope stranger reached by search, detail or overlap (DECISIONS E-12)
--   second     friend-of-friend node on the map
create or replace function public.net__person(p_o uuid, p_level text, p_via_tap boolean default false)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  p public.net_people%rowtype;
  e public.net_profile_ext%rowtype;
  out jsonb;
  cf text[];
  contact jsonb;
begin
  select * into p from public.net_people x where x.user_id = p_o limit 1;
  if not found then return null; end if;
  select * into e from public.net_profile_ext x where x.user_id = p_o;
  cf := coalesce(e.contact_fields, array['email']::text[]);

  out := jsonb_build_object(
    'id', p.user_id,
    'name', p.display_name,
    'institute', p.institute,
    'role_label', p.role_label,
    'role_kind', p.role_kind,
    'photo_url', p.photo_url,
    'headline', e.headline,
    'key_finding', p.key_finding,
    'themes', public.net__themes_json(p_o),
    'ask_text', e.ask_text,
    'offer_text', e.offer_text,
    'is_presenter', p.is_presenter
  );

  if p_level <> 'second' then
    out := out || jsonb_build_object(
      'bio', e.bio,
      'paper_title', p.paper_title,
      'paper_url', p.paper_url,
      'slides_url', p.slides_url,
      'session_id', p.session_id,
      'session_title', p.session_title,
      'session_start', p.session_start,
      'room', p.room
    );
  end if;

  if p_level in ('self', 'met', 'accepted') then
    out := out || jsonb_build_object(
      'interests', to_jsonb(coalesce(e.interests, '{}'::text[])),
      'ask_me_about', to_jsonb(coalesce(e.ask_me_about, '{}'::text[])),
      'open_to', to_jsonb(coalesce(e.open_to, '{}'::text[]))
    );
  end if;

  if p_level = 'self' then
    cf := array['email','phone','linkedin']::text[];
  end if;
  if p_level in ('self', 'accepted') or (p_via_tap and p_level <> 'second' and coalesce(e.share_on_tap, false)) then
    contact := '{}'::jsonb;
    if 'email' = any(cf) then contact := contact || jsonb_build_object('email', p.email); end if;
    if 'phone' = any(cf) then contact := contact || jsonb_build_object('phone', p.phone); end if;
    if 'linkedin' = any(cf) then contact := contact || jsonb_build_object('linkedin', p.linkedin); end if;
    out := out || jsonb_build_object('contact', contact);
  end if;

  return out;
end $$;

create or replace function public.net__level(p_rel text, p_path text)
returns text language sql immutable set search_path = '' as $$
  select case p_rel when 'self' then 'self' when 'accepted' then 'accepted' when 'met' then 'met'
                    else case when p_path = 'tap' then 'tap' else 'directory' end end
$$;

create or replace function public.net__mutual_ids(p_x uuid, p_y uuid)
returns setof uuid language sql stable security definer set search_path = '' as $$
  with cx as (
    select case when c.a = p_x then c.b else c.a end as id from public.net_connections c
    where (c.a = p_x or c.b = p_x) and c.removed_at is null
  ), cy as (
    select case when c.a = p_y then c.b else c.a end as id from public.net_connections c
    where (c.a = p_y or c.b = p_y) and c.removed_at is null
  )
  select cx.id from cx join cy on cx.id = cy.id
  where not public.net__blocked(p_x, cx.id) and not public.net__blocked(p_y, cx.id)
$$;

-- Normalise a /t/ parameter. 16 chars: Crockford token (I,L -> 1, O -> 0). 6 chars: printed code.
create or replace function public.net__norm_ref(p_ref text)
returns text language sql immutable set search_path = '' as $$
  select translate(upper(regexp_replace(coalesce(p_ref, ''), '[\s-]', '', 'g')), 'ILO', '110')
$$;

create or replace function public.net__hash_token(p_token text)
returns bytea language sql immutable set search_path = '' as $$
  select pg_catalog.sha256(convert_to(public.net__norm_ref(p_token), 'UTF8'))
$$;

-- Find a card from a token (16) or printed code (6). Codes never resolve unbound cards (activation secret).
create or replace function public.net__card_by_ref(p_ref text)
returns public.net_cards language plpgsql stable security definer set search_path = '' as $$
declare
  r text := public.net__norm_ref(p_ref);
  c public.net_cards%rowtype;
begin
  if char_length(r) = 16 and r ~ '^[0-9A-HJKMNP-TV-Z]{16}$' then
    select * into c from public.net_cards x where x.token_hash = public.net__hash_token(r);
  elsif char_length(r) = 6 then
    select * into c from public.net_cards x
      where x.printed_code = upper(regexp_replace(coalesce(p_ref, ''), '[\s-]', '', 'g')) and x.status <> 'unbound';
  end if;
  return c; -- all-null row when not found
end $$;

create or replace function public.net__rate_ok(p_viewer uuid, p_bucket text, p_kind text, p_max int, p_window interval)
returns boolean language sql stable security definer set search_path = '' as $$
  select (select count(*) from public.net_tap_events t
          where t.kind = p_kind and t.at > now() - p_window
            and ((p_viewer is not null and t.viewer = p_viewer) or (p_viewer is null and t.bucket = p_bucket))) < p_max
$$;

create or replace function public.net__ip_bucket()
returns text language plpgsql stable security definer set search_path = '' as $$
declare h text;
begin
  begin
    h := coalesce(current_setting('request.headers', true), '{}')::json ->> 'x-forwarded-for';
  exception when others then h := null;
  end;
  return encode(pg_catalog.sha256(convert_to(coalesce(split_part(h, ',', 1), 'none'), 'UTF8')), 'hex');
end $$;

create or replace function public.net__audit(p_action text, p_subject text, p_detail jsonb)
returns void language sql security definer set search_path = '' as $$
  insert into public.net_audit (actor, action, subject, detail) values (auth.uid(), p_action, p_subject, p_detail)
$$;

create or replace function public.net__ensure_ext(p_user uuid)
returns void language sql security definer set search_path = '' as $$
  insert into public.net_profile_ext (user_id) values (p_user) on conflict (user_id) do nothing
$$;

create or replace function public.net__random_code()
returns text language plpgsql volatile set search_path = '' as $$
declare
  alphabet constant text := '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
  b bytea := pg_catalog.uuid_send(gen_random_uuid());
  s text := '';
  i int;
begin
  for i in 0..5 loop
    s := s || substr(alphabet, (get_byte(b, i) % 31) + 1, 1);
  end loop;
  return s;
end $$;

-- Upsert or revive an edge (canonical order). Returns true when a new active edge was created.
create or replace function public.net__upsert_edge(p_me uuid, p_other uuid, p_source text, p_context text,
                                                   p_session text, p_card uuid)
returns boolean language plpgsql security definer set search_path = '' as $$
declare
  lo uuid := least(p_me, p_other);
  hi uuid := greatest(p_me, p_other);
  existing public.net_connections%rowtype;
begin
  select * into existing from public.net_connections c where c.a = lo and c.b = hi for update;
  if not found then
    insert into public.net_connections (a, b, initiator, source, context, card_id, session_id)
    values (lo, hi, p_me, p_source, p_context, p_card, p_session);
    return true;
  elsif existing.removed_at is not null then
    update public.net_connections c
       set initiator = p_me, source = p_source, context = p_context, card_id = p_card, session_id = p_session,
           created_at = now(), removed_at = null, removed_by = null
     where c.a = lo and c.b = hi;
    return true;
  end if;
  return false;
end $$;

-- D-5: which sources draw an edge. Edit here to widen (for example add 'table').
create or replace function public.net__edge_sources()
returns text[] language sql immutable set search_path = '' as $$ select array['tap','scan','coffee']::text[] $$;

-- Log a meeting and draw an edge when allowed (DECISIONS E-07).
create or replace function public.net__record(p_me uuid, p_other uuid, p_source text, p_context text, p_session text)
returns boolean language plpgsql security definer set search_path = '' as $$
declare
  reciprocal boolean;
begin
  insert into public.net_meetings (actor, other, source, context, session_id)
  values (p_me, p_other, p_source, left(p_context, 120), p_session);
  if not (p_source = any(public.net__edge_sources())) then return false; end if;
  select exists (select 1 from public.net_meetings m
                 where m.actor = p_other and m.other = p_me and m.at > now() - interval '14 days')
    into reciprocal;
  if reciprocal or public.net_host_confirms_meeting(p_me, p_other, p_source) then
    perform public.net__upsert_edge(p_me, p_other, p_source, left(p_context, 120), p_session, null);
    return true;
  end if;
  return false;
end $$;

-- ---------------------------------------------------------------- flags and themes

create or replace function public.net_get_feature_flags()
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'tap', public.net__flag('tap'), 'map', public.net__flag('map'), 'overlap', public.net__flag('overlap'),
    'galaxy', public.net__flag('galaxy'), 'digital_pass', public.net__flag('digital_pass'))
$$;

create or replace function public.net_list_themes()
returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'slug', t.slug, 'label', t.label, 'colour', t.colour)
                            order by t.sort, t.id), '[]'::jsonb)
  from public.net_themes t
$$;

-- ---------------------------------------------------------------- tap flow

-- anon. No personal data. Lets the signed-out tap screen choose: sign in, replaced, unknown, paused.
create or replace function public.net_resolve_token(p_token text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  c public.net_cards%rowtype;
  bucket text := public.net__ip_bucket();
  st text;
begin
  if not public.net__flag('tap') then return jsonb_build_object('state', 'paused'); end if;
  if not public.net__rate_ok(null, bucket, 'resolve', 60, interval '1 minute') then
    return jsonb_build_object('state', 'limited');
  end if;
  c := public.net__card_by_ref(p_token);
  st := case when c.id is null then 'unknown' else c.status end;
  insert into public.net_tap_events (viewer, bucket, kind, token_hash, result)
  values (auth.uid(), bucket, 'resolve', c.token_hash, st);
  return jsonb_build_object('state', st);
end $$;

-- Signed in. Read-only for the graph (writes only an audit/rate-limit event). Never creates a connection.
create or replace function public.net_get_profile_by_token(p_token text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  c public.net_cards%rowtype;
  rel text;
  owner_session text;
  my_session text;
  result text;
begin
  if not public.net__flag('tap') then return jsonb_build_object('state', 'paused'); end if;
  if not public.net__rate_ok(me, null, 'profile', 30, interval '1 minute') then
    return jsonb_build_object('state', 'limited');
  end if;
  c := public.net__card_by_ref(p_token);

  if c.id is null then result := 'unknown';
  elsif c.status = 'revoked' then result := 'revoked';
  elsif c.status = 'unbound' then result := 'unbound';
  elsif not public.net__is_person(c.user_id) then result := 'unknown';
  else
    rel := public.net__relation(me, c.user_id);
    result := case rel when 'blocked' then 'unknown' when 'self' then 'self' else 'active' end;
  end if;

  insert into public.net_tap_events (viewer, kind, token_hash, result) values (me, 'profile', c.token_hash, result);

  if result in ('unknown', 'revoked', 'unbound') then
    return jsonb_build_object('state', result);
  end if;
  if result = 'self' then
    return jsonb_build_object('state', 'self', 'person', public.net__person(me, 'self'));
  end if;

  select p.session_id into owner_session from public.net_people p where p.user_id = c.user_id limit 1;
  select p.session_id into my_session from public.net_people p where p.user_id = me limit 1;

  return jsonb_build_object(
    'state', 'active',
    'person', public.net__person(c.user_id, public.net__level(rel, 'tap'), true),
    'connection', jsonb_build_object('state', case when public.net__met(me, c.user_id) then 'connected' else 'none' end),
    'mutual_count', (select count(*) from public.net__mutual_ids(me, c.user_id)),
    'in_your_session', (owner_session is not null and owner_session = my_session)
  );
end $$;

-- Idempotent connect after the tap screen renders. Physical card passes scope, never a block.
create or replace function public.net_connect_via_card(p_token text, p_source text default 'tap',
                                                       p_session_id text default null, p_context text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  c public.net_cards%rowtype;
  created boolean;
  owner_share boolean;
begin
  if not public.net__flag('tap') then return jsonb_build_object('error', 'paused'); end if;
  if p_source not in ('tap', 'scan') then return jsonb_build_object('error', 'bad_source'); end if;
  if not public.net__rate_ok(me, null, 'connect', 60, interval '1 minute') then
    return jsonb_build_object('error', 'limited');
  end if;
  c := public.net__card_by_ref(p_token);
  insert into public.net_tap_events (viewer, kind, token_hash, result)
  values (me, 'connect', c.token_hash, coalesce(c.status, 'unknown'));

  if c.id is null or c.status <> 'active' or public.net__blocked(me, c.user_id)
     or not public.net__is_person(c.user_id) then
    return jsonb_build_object('error', 'unknown');
  end if;
  if c.user_id = me then return jsonb_build_object('error', 'self'); end if;

  created := public.net__upsert_edge(me, c.user_id, p_source, left(p_context, 120), p_session_id, c.id);
  insert into public.net_meetings (actor, other, source, context, session_id)
  values (me, c.user_id, p_source, left(p_context, 120), p_session_id);

  select coalesce((select e.share_on_tap from public.net_profile_ext e where e.user_id = c.user_id), false) into owner_share;
  if owner_share then
    insert into public.net_contact_grants (owner, viewer, source) values (c.user_id, me, 'share_on_tap')
    on conflict (owner, viewer) do update set revoked_at = null, granted_at = now(), source = excluded.source
      where public.net_contact_grants.revoked_at is not null;
  end if;

  return jsonb_build_object('created', created, 'other_id', c.user_id, 'undo_seconds', 8);
end $$;

-- Initiator only, within 8 seconds (plus 1 s network grace) of creation.
create or replace function public.net_undo_connection(p_other uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  n int;
begin
  update public.net_connections c
     set removed_at = now(), removed_by = me
   where c.a = least(me, p_other) and c.b = greatest(me, p_other)
     and c.removed_at is null and c.initiator = me and c.created_at > now() - interval '9 seconds';
  get diagnostics n = row_count;
  if n = 0 then return jsonb_build_object('error', 'expired'); end if;
  update public.net_contact_grants g set revoked_at = now()
   where g.owner = p_other and g.viewer = me and g.source = 'share_on_tap' and g.revoked_at is null;
  return jsonb_build_object('ok', true);
end $$;

-- The single write path for every non-card meeting source.
create or replace function public.net_record_meeting(p_other uuid, p_source text, p_context text default null,
                                                     p_session_id text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  edge boolean;
begin
  if p_source not in ('tap','scan','coffee','circle','office_hours','table') then
    return jsonb_build_object('error', 'bad_source');
  end if;
  if p_other = me then return jsonb_build_object('error', 'self'); end if;
  if not public.net__is_person(p_other) or public.net__blocked(me, p_other) then
    return jsonb_build_object('error', 'unknown');
  end if;
  if not public.net__rate_ok(me, null, 'meeting', 60, interval '1 minute') then
    return jsonb_build_object('error', 'limited');
  end if;
  insert into public.net_tap_events (viewer, kind, result) values (me, 'meeting', p_source);
  edge := public.net__record(me, p_other, p_source, p_context, p_session_id);
  return jsonb_build_object('recorded', true, 'edge', edge);
end $$;

-- ---------------------------------------------------------------- cards and pass

create or replace function public.net_activate_card(p_code text, p_scope text default 'presenters',
                                                    p_token text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  code text := upper(regexp_replace(coalesce(p_code, ''), '[\s-]', '', 'g'));
  c public.net_cards%rowtype;
  cur public.net_cards%rowtype;
begin
  if p_scope not in ('presenters', 'all', 'met') then return jsonb_build_object('error', 'bad_scope'); end if;
  if not public.net__rate_ok(me, null, 'activate_fail', 10, interval '1 hour') then
    return jsonb_build_object('error', 'limited');
  end if;
  select * into c from public.net_cards x where x.printed_code = code and x.status = 'unbound' for update;
  if not found or (p_token is not null and c.token_hash is distinct from public.net__hash_token(p_token)) then
    insert into public.net_tap_events (viewer, kind, result) values (me, 'activate_fail', 'bad_code');
    return jsonb_build_object('error', 'bad_code');
  end if;
  select * into cur from public.net_cards x where x.user_id = me and x.status = 'active' for update;
  if found and cur.chip <> 'virtual' then return jsonb_build_object('error', 'already_active'); end if;
  if found then
    update public.net_cards x set status = 'revoked', revoked_at = now() where x.id = cur.id;
  end if;

  update public.net_cards x set status = 'active', user_id = me, bound_at = now(), bound_by = me where x.id = c.id;
  perform public.net__ensure_ext(me);
  update public.net_profile_ext e set visibility_scope = p_scope, updated_at = now() where e.user_id = me;
  insert into public.net_consents (user_id, key, value, text_version)
  values (me, 'visibility_scope', to_jsonb(p_scope), public.net__consent_version());
  perform public.net__audit('activate_card', c.id::text, jsonb_build_object('code', c.printed_code, 'self', true));
  return jsonb_build_object('ok', true, 'card_id', c.id, 'printed_code', c.printed_code);
end $$;

create or replace function public.net_report_lost_card()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  n int;
begin
  update public.net_cards x set status = 'revoked', revoked_at = now()
   where x.user_id = me and x.status = 'active' and x.chip <> 'virtual';
  get diagnostics n = row_count;
  perform public.net__audit('report_lost_card', me::text, jsonb_build_object('revoked', n));
  return jsonb_build_object('ok', true, 'revoked', n);
end $$;

create or replace function public.net_get_my_pass()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  c public.net_cards%rowtype;
begin
  select * into c from public.net_cards x where x.user_id = me
   order by (x.status = 'active') desc, coalesce(x.revoked_at, x.bound_at, x.created_at) desc limit 1;
  return jsonb_build_object(
    'card', case when c.id is null then null else jsonb_build_object(
      'status', c.status, 'printed_code', case when c.status = 'active' then c.printed_code end,
      'chip', c.chip, 'virtual', c.chip = 'virtual', 'bound_at', c.bound_at, 'revoked_at', c.revoked_at) end,
    'digital_pass_allowed', public.net__flag('digital_pass') and public.net__is_person(me)
  );
end $$;

create or replace function public.net_issue_digital_pass()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  code text;
  tries int := 0;
begin
  if not public.net__flag('digital_pass') then return jsonb_build_object('error', 'paused'); end if;
  if not public.net__is_person(me) then return jsonb_build_object('error', 'not_registered'); end if;
  if exists (select 1 from public.net_cards x where x.user_id = me and x.status = 'active') then
    return public.net_get_my_pass();
  end if;
  loop
    code := public.net__random_code();
    exit when not exists (select 1 from public.net_cards x where x.printed_code = code);
    tries := tries + 1;
    if tries > 20 then return jsonb_build_object('error', 'try_again'); end if;
  end loop;
  insert into public.net_cards (printed_code, chip, status, user_id, bound_at, bound_by, batch)
  values (code, 'virtual', 'active', me, now(), me, 'digital');
  perform public.net__ensure_ext(me);
  perform public.net__audit('issue_digital_pass', me::text, jsonb_build_object('code', code));
  return public.net_get_my_pass();
end $$;

-- ---------------------------------------------------------------- settings and consent

create or replace function public.net_get_my_settings()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  e public.net_profile_ext%rowtype;
  p public.net_people%rowtype;
begin
  select * into e from public.net_profile_ext x where x.user_id = me;
  select * into p from public.net_people x where x.user_id = me limit 1;
  return jsonb_build_object(
    'visibility_scope', coalesce(e.visibility_scope, 'presenters'),
    'share_on_tap', coalesce(e.share_on_tap, false),
    'second_degree', coalesce(e.second_degree, false),
    'discoverable', coalesce(e.discoverable, false),
    'contact_fields', to_jsonb(coalesce(e.contact_fields, array['email']::text[])),
    'followup_reminder', coalesce(e.followup_reminder, false),
    'headline', e.headline, 'bio', e.bio, 'ask_text', e.ask_text, 'offer_text', e.offer_text,
    'interests', to_jsonb(coalesce(e.interests, '{}'::text[])),
    'ask_me_about', to_jsonb(coalesce(e.ask_me_about, '{}'::text[])),
    'open_to', to_jsonb(coalesce(e.open_to, '{}'::text[])),
    'themes', public.net__themes_json(me),
    'consent_version', public.net__consent_version(),
    'registered', p.user_id is not null,
    'is_presenter', coalesce(p.is_presenter, false),
    'name', p.display_name,
    'has_contact', jsonb_build_object('email', p.email is not null, 'phone', p.phone is not null,
                                      'linkedin', p.linkedin is not null)
  );
end $$;

-- Appends a consent row and applies the setting. Takes effect on the next request.
create or replace function public.net_set_consent(p_key text, p_value jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  arr text[];
begin
  perform public.net__ensure_ext(me);
  if p_key = 'visibility_scope' then
    if jsonb_typeof(p_value) <> 'string' or (p_value #>> '{}') not in ('presenters', 'all', 'met') then
      return jsonb_build_object('error', 'bad_value');
    end if;
    update public.net_profile_ext e set visibility_scope = p_value #>> '{}', updated_at = now() where e.user_id = me;
  elsif p_key in ('share_on_tap', 'second_degree', 'discoverable', 'followup_reminder') then
    if jsonb_typeof(p_value) <> 'boolean' then return jsonb_build_object('error', 'bad_value'); end if;
    execute format('update public.net_profile_ext set %I = $1, updated_at = now() where user_id = $2', p_key)
      using (p_value #>> '{}')::boolean, me;
  elsif p_key = 'contact_fields' then
    if jsonb_typeof(p_value) <> 'array' then return jsonb_build_object('error', 'bad_value'); end if;
    select coalesce(array_agg(distinct v), '{}') into arr from jsonb_array_elements_text(p_value) v;
    if not (arr <@ array['email','phone','linkedin']::text[]) then return jsonb_build_object('error', 'bad_value'); end if;
    update public.net_profile_ext e set contact_fields = arr, updated_at = now() where e.user_id = me;
  else
    return jsonb_build_object('error', 'bad_key');
  end if;
  insert into public.net_consents (user_id, key, value, text_version)
  values (me, p_key, p_value, public.net__consent_version());
  return public.net_get_my_settings();
end $$;

-- Profile extension edited in onboarding step 2 or the module's editor (K-30, K-31).
create or replace function public.net_update_profile_ext(p jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  ids smallint[];
  arr_interests text[];
  arr_ask text[];
  arr_open text[];
begin
  if not public.net__is_person(me) then return jsonb_build_object('error', 'not_registered'); end if;
  perform public.net__ensure_ext(me);
  begin
    select coalesce(array_agg(trim(v)) filter (where trim(v) <> ''), '{}') into arr_interests
      from jsonb_array_elements_text(coalesce(p -> 'interests', '[]')) v;
    select coalesce(array_agg(trim(v)) filter (where trim(v) <> ''), '{}') into arr_ask
      from jsonb_array_elements_text(coalesce(p -> 'ask_me_about', '[]')) v;
    select coalesce(array_agg(trim(v)) filter (where trim(v) <> ''), '{}') into arr_open
      from jsonb_array_elements_text(coalesce(p -> 'open_to', '[]')) v;
    update public.net_profile_ext e set
      headline = nullif(trim(p ->> 'headline'), ''),
      bio = nullif(trim(p ->> 'bio'), ''),
      ask_text = nullif(trim(p ->> 'ask_text'), ''),
      offer_text = nullif(trim(p ->> 'offer_text'), ''),
      interests = case when p ? 'interests' then arr_interests else e.interests end,
      ask_me_about = case when p ? 'ask_me_about' then arr_ask else e.ask_me_about end,
      open_to = case when p ? 'open_to' then arr_open else e.open_to end,
      updated_at = now()
    where e.user_id = me;
  exception when check_violation then
    return jsonb_build_object('error', 'invalid');
  end;

  if p ? 'theme_ids' then
    select coalesce(array_agg(distinct (v)::smallint), '{}') into ids from jsonb_array_elements_text(p -> 'theme_ids') v;
    if cardinality(ids) > 3 then return jsonb_build_object('error', 'too_many_themes'); end if;
    delete from public.net_profile_themes t where t.user_id = me;
    insert into public.net_profile_themes (user_id, theme_id, rank)
    select me, d.id, (row_number() over (order by d.o))::smallint
    from (select (v.value)::smallint as id, min(v.ordinality) as o
          from jsonb_array_elements_text(p -> 'theme_ids') with ordinality v
          where exists (select 1 from public.net_themes t where t.id = (v.value)::smallint)
          group by (v.value)::smallint) d;
  end if;

  perform public.net_refresh_similarity(me);
  return public.net_get_my_settings();
end $$;

-- Removes the caller's card link, connections, notes, grants, meetings and extension row (DECISIONS E-14).
create or replace function public.net_withdraw_all()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  n_conn int; n_notes int; n_cards int;
begin
  delete from public.net_connections c where c.a = me or c.b = me;
  get diagnostics n_conn = row_count;
  delete from public.net_person_notes n where n.author = me or n.about = me;
  get diagnostics n_notes = row_count;
  delete from public.net_contact_grants g where g.owner = me or g.viewer = me;
  delete from public.net_meetings m where m.actor = me or m.other = me;
  delete from public.net_similarity_edges s where s.a = me or s.b = me;
  delete from public.net_profile_themes t where t.user_id = me;
  delete from public.net_profile_ext e where e.user_id = me;
  update public.net_cards x set status = 'revoked', revoked_at = now() where x.user_id = me and x.status = 'active';
  get diagnostics n_cards = row_count;
  insert into public.net_consents (user_id, key, value, text_version)
  values (me, 'withdraw_all', 'true'::jsonb, public.net__consent_version());
  perform public.net__audit('withdraw_all', me::text, jsonb_build_object('connections', n_conn, 'cards', n_cards));
  return jsonb_build_object('ok', true, 'connections', n_conn, 'notes', n_notes, 'cards', n_cards);
end $$;

-- ---------------------------------------------------------------- contact grants (ADDITION, data-contract NEW)

create or replace function public.net_grant_contact(p_viewer uuid, p_source text default 'manual')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
begin
  if p_source not in ('coffee', 'manual') then return jsonb_build_object('error', 'bad_source'); end if;
  if p_viewer = me then return jsonb_build_object('error', 'self'); end if;
  if not public.net__is_person(p_viewer) or public.net__blocked(me, p_viewer) then
    return jsonb_build_object('error', 'unknown');
  end if;
  insert into public.net_contact_grants (owner, viewer, source) values (me, p_viewer, p_source)
  on conflict (owner, viewer) do update set revoked_at = null, granted_at = now(), source = excluded.source;
  if p_source = 'coffee' then
    perform public.net__record(me, p_viewer, 'coffee', null, null);
  end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.net_revoke_contact(p_viewer uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  update public.net_contact_grants g set revoked_at = now()
   where g.owner = me and g.viewer = p_viewer and g.revoked_at is null;
  return jsonb_build_object('ok', true);
end $$;

-- ---------------------------------------------------------------- profile detail (K-33)

-- Path from viewer to owner of up to 3 hops, through people the viewer may see. Null if none.
create or replace function public.net__path_to(p_me uuid, p_o uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  x uuid; y uuid;
begin
  if public.net__met(p_me, p_o) then
    return jsonb_build_array(p_me, p_o);
  end if;
  select m into x from public.net__mutual_ids(p_me, p_o) m limit 1;
  if x is not null then return jsonb_build_array(p_me, x, p_o); end if;
  -- me - x - y - o : y must be visible to me as a second-degree person
  select d.id, s.id into x, y
  from (select case when c.a = p_me then c.b else c.a end as id from public.net_connections c
        where (c.a = p_me or c.b = p_me) and c.removed_at is null) d
  join lateral (select case when c2.a = d.id then c2.b else c2.a end as id from public.net_connections c2
                where (c2.a = d.id or c2.b = d.id) and c2.removed_at is null) s on s.id <> p_me
  where public.net__met(s.id, p_o)
    and coalesce((select e.second_degree from public.net_profile_ext e where e.user_id = s.id), false)
    and public.net__can_see(p_me, s.id)
    and not public.net__blocked(p_o, d.id) and not public.net__blocked(p_o, s.id)
  limit 1;
  if y is not null then return jsonb_build_array(p_me, x, y, p_o); end if;
  return null;
end $$;

create or replace function public.net_get_profile_detail(p_user uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  rel text;
  lvl text;
  conn public.net_connections%rowtype;
  path jsonb;
  path_named jsonb;
  mutual jsonb;
  shared jsonb;
  note text;
begin
  if not public.net__can_see(me, p_user) then return null; end if;
  rel := public.net__relation(me, p_user);
  lvl := public.net__level(rel, 'directory');
  if rel = 'self' then
    return jsonb_build_object('person', public.net__person(me, 'self'), 'relation', jsonb_build_object('self', true));
  end if;

  select * into conn from public.net_connections c
   where c.a = least(me, p_user) and c.b = greatest(me, p_user) and c.removed_at is null;

  if lvl in ('met', 'accepted') then
    select jsonb_build_object('count', count(*),
             'people', coalesce(jsonb_agg(jsonb_build_object('id', p.user_id, 'name', p.display_name)
                                          order by p.display_name) filter (where p.user_id is not null), '[]'::jsonb))
      into mutual
      from public.net__mutual_ids(me, p_user) m left join public.net_people p on p.user_id = m;
  else
    select jsonb_build_object('count', count(*)) into mutual from public.net__mutual_ids(me, p_user);
  end if;

  path := public.net__path_to(me, p_user);
  if path is not null then
    select jsonb_agg(jsonb_build_object('id', p.user_id, 'name', case when p.user_id = me then 'You' else p.display_name end)
                     order by v.ord)
      into path_named
      from jsonb_array_elements_text(path) with ordinality v(id, ord)
      join public.net_people p on p.user_id = v.id::uuid;
  end if;

  select coalesce(jsonb_agg(distinct x.label), '[]'::jsonb) into shared from (
    select 'Same session: ' || pm.session_title as label
      from public.net_people pm join public.net_people po on po.session_id = pm.session_id
     where pm.user_id = me and po.user_id = p_user and pm.session_id is not null
    union
    select 'Both starred: ' || coalesce(pp.session_title, a.session_id)
      from public.net_starred_sessions a join public.net_starred_sessions b on a.session_id = b.session_id
      left join lateral (select x2.session_title from public.net_people x2 where x2.session_id = a.session_id limit 1) pp on true
     where a.user_id = me and b.user_id = p_user
    union
    select 'Both at ' || coalesce(m.context, replace(m.source, '_', ' '))
      from public.net_meetings m
     where m.source in ('table', 'circle', 'office_hours')
       and ((m.actor = me and m.other = p_user) or (m.actor = p_user and m.other = me))
  ) x;

  select n.body into note from public.net_person_notes n where n.author = me and n.about = p_user;

  return jsonb_build_object(
    'person', public.net__person(p_user, lvl),
    'relation', jsonb_build_object(
      'level', lvl,
      'connection', case when conn.a is null then 'none' else 'connected' end,
      'connected_at', conn.created_at,
      'source', conn.source,
      'context', conn.context,
      'initiator_is_me', conn.initiator = me,
      'contact_granted_to_me', rel = 'accepted',
      'i_shared_contact', public.net__granted(me, p_user)
    ),
    'mutual', mutual,
    'path_to_me', path_named,
    'shared_sessions', shared,
    'note', note
  );
end $$;

-- ---------------------------------------------------------------- notes, connections, blocks, reports

create or replace function public.net_set_note(p_about uuid, p_body text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  if p_about = me or not public.net__is_person(p_about) then return jsonb_build_object('error', 'unknown'); end if;
  if coalesce(trim(p_body), '') = '' then
    delete from public.net_person_notes n where n.author = me and n.about = p_about;
    return jsonb_build_object('ok', true, 'deleted', true);
  end if;
  if char_length(p_body) > 1000 then return jsonb_build_object('error', 'too_long'); end if;
  insert into public.net_person_notes (author, about, body) values (me, p_about, trim(p_body))
  on conflict (author, about) do update set body = excluded.body, updated_at = now();
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.net_remove_connection(p_other uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  update public.net_connections c set removed_at = now(), removed_by = me
   where c.a = least(me, p_other) and c.b = greatest(me, p_other) and c.removed_at is null;
  update public.net_contact_grants g set revoked_at = now()
   where g.revoked_at is null and ((g.owner = me and g.viewer = p_other) or (g.owner = p_other and g.viewer = me and g.source = 'share_on_tap'));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.net_list_connections()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  return coalesce((
    select jsonb_agg(x.row order by x.created_at desc) from (
      select c.created_at, jsonb_build_object(
        'person', public.net__person(o.id, public.net__level(public.net__relation(me, o.id), 'directory')),
        'source', c.source, 'context', c.context, 'session_id', c.session_id, 'created_at', c.created_at,
        'initiator_is_me', c.initiator = me,
        'note', (select n.body from public.net_person_notes n where n.author = me and n.about = o.id),
        'contact_granted_to_me', public.net__granted(o.id, me),
        'i_shared_contact', public.net__granted(me, o.id)
      ) as row
      from public.net_connections c
      cross join lateral (select case when c.a = me then c.b else c.a end as id) o
      where (c.a = me or c.b = me) and c.removed_at is null
        and not public.net__blocked(me, o.id) and public.net__is_person(o.id)
    ) x), '[]'::jsonb);
end $$;

create or replace function public.net_block_user(p_other uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  if p_other = me then return jsonb_build_object('error', 'self'); end if;
  if not exists (select 1 from auth.users u where u.id = p_other) then return jsonb_build_object('ok', true); end if;
  insert into public.net_blocks (blocker, blocked) values (me, p_other) on conflict do nothing;
  update public.net_connections c set removed_at = now(), removed_by = me
   where c.a = least(me, p_other) and c.b = greatest(me, p_other) and c.removed_at is null;
  update public.net_contact_grants g set revoked_at = now()
   where g.revoked_at is null and ((g.owner = me and g.viewer = p_other) or (g.owner = p_other and g.viewer = me));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.net_unblock_user(p_other uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  delete from public.net_blocks k where k.blocker = me and k.blocked = p_other;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.net_report_user(p_other uuid, p_reason text, p_note text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  if p_reason not in ('spam', 'inappropriate', 'impersonation', 'other') then
    return jsonb_build_object('error', 'bad_reason');
  end if;
  if p_other = me or not exists (select 1 from auth.users u where u.id = p_other) then
    return jsonb_build_object('error', 'unknown');
  end if;
  if (select count(*) from public.net_reports r where r.reporter = me and r.created_at > now() - interval '1 hour') >= 10 then
    return jsonb_build_object('error', 'limited');
  end if;
  insert into public.net_reports (reporter, reported, reason, note) values (me, p_other, p_reason, left(p_note, 500));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.net_log_event(p_kind text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  if p_kind not in ('map_open', 'overlap_open', 'list_open', 'client_error', 'export') then
    return jsonb_build_object('error', 'bad_kind');
  end if;
  if exists (select 1 from public.net_metric_events m
             where m.user_id = me and m.kind = p_kind and m.at > now() - interval '30 seconds') then
    return jsonb_build_object('ok', true, 'throttled', true);
  end if;
  insert into public.net_metric_events (kind, user_id) values (p_kind, me);
  return jsonb_build_object('ok', true);
end $$;

-- ===== supabase/migrations/20261114000300_network_graph.sql
-- pan-iim-network: graph, overlap, search and similarity (K-41, K-50, K-53, K-55)

-- Direct connections of p_me that are people and not blocked.
create or replace function public.net__direct_ids(p_me uuid)
returns setof uuid language sql stable security definer set search_path = '' as $$
  select o.id
  from public.net_connections c
  cross join lateral (select case when c.a = p_me then c.b else c.a end as id) o
  where (c.a = p_me or c.b = p_me) and c.removed_at is null
    and not public.net__blocked(p_me, o.id) and public.net__is_person(o.id)
$$;

-- Friends of friends p_me may see: owner opted into second_degree, scope allows, no block.
create or replace function public.net__second_ids(p_me uuid)
returns setof uuid language sql stable security definer set search_path = '' as $$
  with d as (select public.net__direct_ids(p_me) as id),
  cand as (
    select distinct o.id
    from d
    join public.net_connections c on (c.a = d.id or c.b = d.id) and c.removed_at is null
    cross join lateral (select case when c.a = d.id then c.b else c.a end as id) o
    where o.id <> p_me and o.id not in (select id from d)
  )
  select cand.id from cand
  join public.net_profile_ext e on e.user_id = cand.id and e.second_degree
  where public.net__can_see(p_me, cand.id)
$$;

create or replace function public.net__sim(p_x uuid, p_y uuid)
returns real language sql stable security definer set search_path = '' as $$
  select s.score from public.net_similarity_edges s where s.a = least(p_x, p_y) and s.b = greatest(p_x, p_y)
$$;

-- Ego graph: you, your connections, consenting second-degree people. Cap 300 nodes.
create or replace function public.net_get_ego_graph(p_depth int default 2, p_theme_ids int[] default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  cap constant int := 300;
  total int;
  nodes jsonb;
  edges jsonb;
begin
  if not public.net__flag('map') then return jsonb_build_object('paused', true); end if;

  create temporary table if not exists net_tmp_nodes (id uuid primary key, depth int, rank_score real) on commit drop;
  truncate pg_temp.net_tmp_nodes;

  insert into pg_temp.net_tmp_nodes values (me, 0, 2);
  insert into pg_temp.net_tmp_nodes
    select d, 1, coalesce(public.net__sim(me, d), 0) + 1 from public.net__direct_ids(me) d
    on conflict do nothing;
  if coalesce(p_depth, 2) >= 2 then
    insert into pg_temp.net_tmp_nodes
      select s, 2, coalesce(public.net__sim(me, s), 0) from public.net__second_ids(me) s
      on conflict do nothing;
  end if;

  if p_theme_ids is not null and cardinality(p_theme_ids) > 0 then
    delete from pg_temp.net_tmp_nodes n
     where n.depth > 0
       and not exists (select 1 from public.net_profile_themes t where t.user_id = n.id and t.theme_id = any(p_theme_ids));
  end if;

  select count(*) into total from pg_temp.net_tmp_nodes;
  if total > cap then
    delete from pg_temp.net_tmp_nodes n where n.id in (
      select x.id from pg_temp.net_tmp_nodes x where x.depth > 0
      order by x.depth asc, x.rank_score desc, x.id offset cap - 1);
  end if;

  select coalesce(jsonb_agg(
           jsonb_build_object(
             'id', p.user_id,
             'depth', n.depth,
             'name', case when n.depth = 0 then 'You' else p.display_name end,
             'institute', p.institute,
             'role_label', p.role_label,
             'role_kind', p.role_kind,
             'photo_url', p.photo_url,
             'theme_ids', coalesce((select jsonb_agg(t.theme_id order by t.rank) from public.net_profile_themes t
                                    where t.user_id = n.id), '[]'::jsonb),
             'session_id', case when n.depth <= 1 then p.session_id end,
             'degree', (select count(*) from public.net_connections c
                        where (c.a = n.id or c.b = n.id) and c.removed_at is null),
             'mutual', case when n.depth = 0 then 0 else (select count(*) from public.net__mutual_ids(me, n.id)) end,
             'ask_text', e.ask_text,
             'offer_text', e.offer_text
           ) order by n.depth, p.display_name), '[]'::jsonb)
    into nodes
    from pg_temp.net_tmp_nodes n
    join public.net_people p on p.user_id = n.id
    left join public.net_profile_ext e on e.user_id = n.id;

  -- Only edges touching you or a direct connection, so friends-of-friends' own ties are not exposed.
  select coalesce(jsonb_agg(jsonb_build_object(
           'a', c.a, 'b', c.b, 'source', c.source,
           'sim', public.net__sim(c.a, c.b),
           'direct', (c.a = me or c.b = me))), '[]'::jsonb)
    into edges
    from public.net_connections c
    join pg_temp.net_tmp_nodes na on na.id = c.a
    join pg_temp.net_tmp_nodes nb on nb.id = c.b
   where c.removed_at is null and least(na.depth, nb.depth) <= 1;

  return jsonb_build_object('me', me, 'nodes', nodes, 'edges', edges, 'truncated', total > cap, 'total', total);
end $$;

-- Counts and a small preview for the Network home card (no graph library needed).
create or replace function public.net_get_my_network_summary()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  direct_n int;
  second_n int;
  preview jsonb;
  legend jsonb;
begin
  select count(*) into direct_n from public.net__direct_ids(me);
  select count(*) into second_n from public.net__second_ids(me);

  with d as (select id from public.net__direct_ids(me) id order by id limit 6),
  s as (
    select distinct on (o.id) o.id, d.id as parent
    from d join public.net_connections c on (c.a = d.id or c.b = d.id) and c.removed_at is null
    cross join lateral (select case when c.a = d.id then c.b else c.a end as id) o
    where o.id in (select public.net__second_ids(me))
    limit 12
  )
  select coalesce(jsonb_agg(x.j), '[]'::jsonb) into preview from (
    select jsonb_build_object('id', d.id, 'depth', 1, 'parent', me,
             'colour', (select t.colour from public.net_profile_themes pt join public.net_themes t on t.id = pt.theme_id
                        where pt.user_id = d.id and pt.rank = 1)) as j from d
    union all
    select jsonb_build_object('id', s.id, 'depth', 2, 'parent', s.parent,
             'colour', (select t.colour from public.net_profile_themes pt join public.net_themes t on t.id = pt.theme_id
                        where pt.user_id = s.id and pt.rank = 1)) from s
  ) x;

  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'label', t.label, 'colour', t.colour) order by q.n desc), '[]'::jsonb)
    into legend
    from (select pt.theme_id, count(*) n from public.net_profile_themes pt
          where pt.rank = 1 and (pt.user_id in (select public.net__direct_ids(me)) or pt.user_id in (select public.net__second_ids(me)))
          group by pt.theme_id order by count(*) desc limit 3) q
    join public.net_themes t on t.id = q.theme_id;

  return jsonb_build_object('direct', direct_n, 'within_two', direct_n + second_n, 'preview', preview, 'legend', legend);
end $$;

-- Population for overlap. 'network': people in your graph. 'event': discoverable people you may see.
create or replace function public.net__overlap_population(p_me uuid, p_scope text)
returns setof uuid language sql stable security definer set search_path = '' as $$
  select x from public.net__direct_ids(p_me) x where p_scope = 'network'
  union
  select x from public.net__second_ids(p_me) x where p_scope = 'network'
  union
  select p.user_id from public.net_people p
  join public.net_profile_ext e on e.user_id = p.user_id and e.discoverable
  where p_scope = 'event' and p.user_id <> p_me and public.net__can_see(p_me, p.user_id)
$$;

-- Region code from a person's selected-theme membership: A, B, C, AB, AC, BC, ABC (null when none).
create or replace function public.net__region_of(p_user uuid, p_theme_ids int[])
returns text language sql stable security definer set search_path = '' as $$
  select nullif(
    case when exists (select 1 from public.net_profile_themes t where t.user_id = p_user and t.theme_id = p_theme_ids[1]) then 'A' else '' end ||
    case when cardinality(p_theme_ids) >= 2 and exists (select 1 from public.net_profile_themes t where t.user_id = p_user and t.theme_id = p_theme_ids[2]) then 'B' else '' end ||
    case when cardinality(p_theme_ids) >= 3 and exists (select 1 from public.net_profile_themes t where t.user_id = p_user and t.theme_id = p_theme_ids[3]) then 'C' else '' end,
  '')
$$;

create or replace function public.net_venn_counts(p_theme_ids int[], p_scope text default 'network')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  regions jsonb;
  total_scope int;
  total_network int;
  total_event int;
begin
  if not public.net__flag('overlap') then return jsonb_build_object('paused', true); end if;
  if p_theme_ids is null or cardinality(p_theme_ids) not between 1 and 3 then
    return jsonb_build_object('error', 'max_three_themes');
  end if;
  if p_scope not in ('network', 'event') then return jsonb_build_object('error', 'bad_scope'); end if;

  select jsonb_object_agg(r.region, r.n), sum(r.n) into regions, total_scope from (
    select public.net__region_of(x, p_theme_ids) region, count(*) n
    from public.net__overlap_population(me, p_scope) x
    group by 1 having public.net__region_of(x, p_theme_ids) is not null) r;

  select count(*) into total_network from public.net__overlap_population(me, 'network') x
   where public.net__region_of(x, p_theme_ids) is not null;
  select count(*) into total_event from public.net__overlap_population(me, 'event') x
   where public.net__region_of(x, p_theme_ids) is not null;

  return jsonb_build_object(
    'theme_ids', to_jsonb(p_theme_ids), 'scope', p_scope,
    'regions', coalesce(regions, '{}'::jsonb), 'total', coalesce(total_scope, 0),
    'totals', jsonb_build_object('network', total_network, 'event', total_event));
end $$;

create or replace function public.net_list_region(p_theme_ids int[], p_region text, p_scope text default 'network',
                                                  p_limit int default 50, p_offset int default 0)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  if not public.net__flag('overlap') then return jsonb_build_object('paused', true); end if;
  if p_theme_ids is null or cardinality(p_theme_ids) not between 1 and 3 then
    return jsonb_build_object('error', 'max_three_themes');
  end if;
  if p_scope not in ('network', 'event') then return jsonb_build_object('error', 'bad_scope'); end if;
  return jsonb_build_object('people', coalesce((
    select jsonb_agg(public.net__list_item(me, q.id) order by q.name)
    from (select x as id, p.display_name as name
          from public.net__overlap_population(me, p_scope) x
          join public.net_people p on p.user_id = x
          where public.net__region_of(x, p_theme_ids) = p_region
          order by p.display_name, x
          limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0)) q
  ), '[]'::jsonb));
end $$;

-- Small row for lists (search, regions): directory-level fields only, never contact.
create or replace function public.net__list_item(p_me uuid, p_o uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'id', p.user_id, 'name', p.display_name, 'institute', p.institute, 'role_label', p.role_label,
    'role_kind', p.role_kind, 'photo_url', p.photo_url, 'paper_title', p.paper_title, 'session_id', p.session_id,
    'headline', e.headline, 'themes', public.net__themes_json(p.user_id),
    'connected', public.net__met(p_me, p.user_id))
  from public.net_people p left join public.net_profile_ext e on e.user_id = p.user_id
  where p.user_id = p_o limit 1
$$;

create or replace function public.net_search_people(p_q text default null, p_theme_ids int[] default null,
                                                    p_institute text default null, p_role_kind text default null,
                                                    p_session_id text default null, p_limit int default 30)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := public.net__uid();
  q text := nullif(trim(coalesce(p_q, '')), '');
begin
  return jsonb_build_object('people', coalesce((
    select jsonb_agg(public.net__list_item(me, r.user_id) order by r.display_name) from (
      select p.user_id, p.display_name
      from public.net_people p
      left join public.net_profile_ext e on e.user_id = p.user_id
      where p.user_id <> me
        and (q is null or p.display_name ilike '%' || q || '%' or p.institute ilike '%' || q || '%'
             or p.paper_title ilike '%' || q || '%' or e.headline ilike '%' || q || '%'
             or exists (select 1 from unnest(coalesce(e.interests, '{}')) i where i ilike '%' || q || '%'))
        and (p_theme_ids is null or cardinality(p_theme_ids) = 0 or exists (
             select 1 from public.net_profile_themes t where t.user_id = p.user_id and t.theme_id = any(p_theme_ids)))
        and (p_institute is null or p.institute = p_institute)
        and (p_role_kind is null or p.role_kind = p_role_kind)
        and (p_session_id is null or p.session_id = p_session_id)
        and public.net__can_see(me, p.user_id)
      order by p.display_name
      limit least(greatest(coalesce(p_limit, 30), 1), 50)
    ) r), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------- similarity (K-50)
-- S = 0.40 J(themes) + 0.25 cos(interests) + 0.20 J(starred) + 0.15 min(1, mutual/5)
-- Without starred sessions: 0.50, 0.3125, 0.1875 (same ratios renormalised).

create or replace function public.net__sim_weights()
returns real[] language sql stable set search_path = '' as $$
  select case when public.net_has_starred_sessions()
              then array[0.40, 0.25, 0.20, 0.15]::real[]
              else array[0.50, 0.3125, 0.0, 0.1875]::real[] end
$$;

create or replace function public.net__jaccard(p_x text[], p_y text[])
returns real language sql immutable set search_path = '' as $$
  select case when u = 0 then 0 else i::real / u end
  from (select (select count(*) from (select unnest(p_x) intersect select unnest(p_y)) q) i,
               (select count(*) from (select unnest(p_x) union select unnest(p_y)) q) u) z
$$;

create or replace function public.net__cosine(p_x text[], p_y text[])
returns real language sql immutable set search_path = '' as $$
  select case when nx = 0 or ny = 0 then 0 else i / sqrt(nx::real * ny) end::real
  from (select (select count(*) from (select unnest(p_x) intersect select unnest(p_y)) q) i,
               (select count(distinct v) from unnest(p_x) v) nx,
               (select count(distinct v) from unnest(p_y) v) ny) z
$$;

-- Candidate pairs share a theme, an interest, a starred session or a connection. p_user limits to one person.
create or replace function public.net__similarity_pairs(p_user uuid default null)
returns table (a uuid, b uuid, score real)
language sql stable security definer set search_path = '' as $$
  -- Set-based: shared counts per pair come from grouped self-joins; no per-pair function calls.
  with w as (select public.net__sim_weights() as w),
  tr as (select t.user_id u, t.theme_id::text v from public.net_profile_themes t),
  ir as (select distinct e.user_id u, lower(x) v from public.net_profile_ext e, unnest(e.interests) x),
  sr as (select distinct s.user_id u, s.session_id v from public.net_starred_sessions s),
  adj as (select c.a x, c.b y from public.net_connections c where c.removed_at is null
          union all select c.b, c.a from public.net_connections c where c.removed_at is null),
  nt as (select u, count(*) n from tr group by u),
  ni as (select u, count(*) n from ir group by u),
  ns as (select u, count(*) n from sr group by u),
  pairs as (
    select least(r1.u, r2.u) a, greatest(r1.u, r2.u) b, count(*) st, 0::bigint si, 0::bigint ss, 0::bigint m
      from (select * from tr where p_user is null or u = p_user) r1 join tr r2 on r1.v = r2.v
       and ((p_user is null and r1.u < r2.u) or (p_user is not null and r1.u <> r2.u)) group by 1, 2
    union all
    select least(r1.u, r2.u), greatest(r1.u, r2.u), 0, count(*), 0, 0
      from (select * from ir where p_user is null or u = p_user) r1 join ir r2 on r1.v = r2.v
       and ((p_user is null and r1.u < r2.u) or (p_user is not null and r1.u <> r2.u)) group by 1, 2
    union all
    select least(r1.u, r2.u), greatest(r1.u, r2.u), 0, 0, count(*), 0
      from (select * from sr where p_user is null or u = p_user) r1 join sr r2 on r1.v = r2.v
       and ((p_user is null and r1.u < r2.u) or (p_user is not null and r1.u <> r2.u)) group by 1, 2
    union all
    select least(j1.x, j2.x), greatest(j1.x, j2.x), 0, 0, 0, count(*)
      from (select * from adj where p_user is null or x = p_user) j1 join adj j2 on j1.y = j2.y
       and ((p_user is null and j1.x < j2.x) or (p_user is not null and j1.x <> j2.x)) group by 1, 2
  ),
  agg as (select p.a, p.b, sum(p.st) st, sum(p.si) si, sum(p.ss) ss, sum(p.m) m from pairs p group by p.a, p.b)
  select g.a, g.b, least(1.0, greatest(0.0,
      w.w[1] * coalesce(g.st::real / nullif(coalesce(ta.n, 0) + coalesce(tb.n, 0) - g.st, 0), 0)
    + w.w[2] * coalesce(g.si::real / nullif(sqrt(coalesce(ia.n, 0)::real * coalesce(ib.n, 0)), 0), 0)
    + w.w[3] * coalesce(g.ss::real / nullif(coalesce(sa.n, 0) + coalesce(sb.n, 0) - g.ss, 0), 0)
    + w.w[4] * least(1.0, g.m / 5.0)))::real
  from agg g cross join w
  left join nt ta on ta.u = g.a left join nt tb on tb.u = g.b
  left join ni ia on ia.u = g.a left join ni ib on ib.u = g.b
  left join ns sa on sa.u = g.a left join ns sb on sb.u = g.b
$$;

-- Keep the top 8 edges per person among the given pairs.
create or replace function public.net__store_top8(p_user uuid default null)
returns int language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  if p_user is null then
    delete from public.net_similarity_edges;
  else
    delete from public.net_similarity_edges s where s.a = p_user or s.b = p_user;
  end if;
  insert into public.net_similarity_edges (a, b, score)
  select distinct on (r.a, r.b) r.a, r.b, r.score from (
    select p.a, p.b, p.score,
           row_number() over (partition by p.a order by p.score desc, p.b) ra,
           row_number() over (partition by p.b order by p.score desc, p.a) rb
    from public.net__similarity_pairs(p_user) p where p.score > 0
  ) r
  where r.ra <= 8 or r.rb <= 8
  on conflict (a, b) do update set score = excluded.score, computed_at = now();
  get diagnostics n = row_count;
  return n;
end $$;

create or replace function public.net_refresh_similarity(p_user uuid)
returns int language sql security definer set search_path = '' as $$ select public.net__store_top8(p_user) $$;

-- Nightly sweep (pg_cron) or by hand.
create or replace function public.net_refresh_similarity_all()
returns int language sql security definer set search_path = '' as $$ select public.net__store_top8(null) $$;

-- P2 K-55: suggestions among discoverable, unconnected people (cut-order step 1; cheap, so shipped behind 'galaxy').
create or replace function public.net_suggest_people(p_limit int default 10)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  if not public.net__flag('galaxy') then return jsonb_build_object('paused', true); end if;
  return jsonb_build_object('people', coalesce((
    select jsonb_agg(public.net__list_item(me, q.id) order by q.score desc) from (
      select case when s.a = me then s.b else s.a end id, s.score
      from public.net_similarity_edges s
      join public.net_profile_ext e on e.user_id = (case when s.a = me then s.b else s.a end) and e.discoverable
      where (s.a = me or s.b = me)
        and not public.net__met(me, case when s.a = me then s.b else s.a end)
        and public.net__can_see(me, case when s.a = me then s.b else s.a end)
      order by s.score desc limit least(greatest(coalesce(p_limit, 10), 1), 10)) q), '[]'::jsonb));
end $$;

-- ===== supabase/migrations/20261114000400_network_admin.sql
-- pan-iim-network: desk console, metrics, kill switch, retention (K-27, K-60, K-61, K-62, K-64)
-- Every staff function checks net_is_staff() (defined in host_mapping.sql) and writes net_audit.

create or replace function public.net__require_staff()
returns uuid language plpgsql stable security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  if not public.net_is_staff() then raise exception 'net:forbidden' using errcode = 'P0001'; end if;
  return me;
end $$;

create or replace function public.net_admin_whoami()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare me uuid := public.net__uid();
begin
  return jsonb_build_object('staff', public.net_is_staff(),
                            'role', case when public.net_is_admin() then 'admin' when public.net_is_staff() then 'desk' end);
end $$;

create or replace function public.net__card_json(c public.net_cards)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('id', c.id, 'printed_code', c.printed_code, 'chip', c.chip, 'status', c.status,
    'user_id', c.user_id, 'user_name', (select p.display_name from public.net_people p where p.user_id = c.user_id limit 1),
    'batch', c.batch, 'bound_at', c.bound_at, 'revoked_at', c.revoked_at, 'created_at', c.created_at)
$$;

create or replace function public.net_admin_find_delegate(p_q text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare q text := nullif(trim(coalesce(p_q, '')), '');
begin
  perform public.net__require_staff();
  if q is null or char_length(q) < 2 then return jsonb_build_object('people', '[]'::jsonb); end if;
  return jsonb_build_object('people', coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', p.user_id, 'name', p.display_name, 'institute', p.institute, 'email', p.email,
             'is_presenter', p.is_presenter,
             'card', (select public.net__card_json(c) from public.net_cards c
                      where c.user_id = p.user_id and c.status = 'active' limit 1)) order by p.display_name)
    from (select * from public.net_people x
          where x.display_name ilike '%' || q || '%' or x.email ilike '%' || q || '%' or x.institute ilike '%' || q || '%'
          order by x.display_name limit 25) p), '[]'::jsonb));
end $$;

create or replace function public.net_admin_bind_card(p_user uuid, p_code text, p_scope text default 'presenters')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := public.net__require_staff();
  code text := upper(regexp_replace(coalesce(p_code, ''), '[\s-]', '', 'g'));
  c public.net_cards%rowtype;
  cur public.net_cards%rowtype;
begin
  if p_scope not in ('presenters', 'all', 'met') then return jsonb_build_object('error', 'bad_scope'); end if;
  if not public.net__is_person(p_user) then return jsonb_build_object('error', 'not_registered'); end if;
  select * into c from public.net_cards x where x.printed_code = code for update;
  if not found then return jsonb_build_object('error', 'bad_code'); end if;
  if c.status <> 'unbound' then return jsonb_build_object('error', 'card_' || c.status); end if;
  select * into cur from public.net_cards x where x.user_id = p_user and x.status = 'active' for update;
  if found and cur.chip <> 'virtual' then return jsonb_build_object('error', 'already_active'); end if;
  if found then update public.net_cards x set status = 'revoked', revoked_at = now() where x.id = cur.id; end if;
  update public.net_cards x set status = 'active', user_id = p_user, bound_at = now(), bound_by = actor where x.id = c.id;
  perform public.net__ensure_ext(p_user);
  if not exists (select 1 from public.net_consents k where k.user_id = p_user and k.key = 'visibility_scope') then
    update public.net_profile_ext e set visibility_scope = p_scope, updated_at = now() where e.user_id = p_user;
    insert into public.net_consents (user_id, key, value, text_version)
    values (p_user, 'visibility_scope', to_jsonb(p_scope), public.net__consent_version() || '+desk');
  end if;
  perform public.net__audit('admin_bind_card', c.id::text, jsonb_build_object('user', p_user, 'code', code));
  return jsonb_build_object('ok', true, 'card_id', c.id);
end $$;

create or replace function public.net_admin_unbind_card(p_card_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  perform public.net__require_staff();
  update public.net_cards x set status = 'unbound', user_id = null, bound_at = null, bound_by = null
   where x.id = p_card_id and x.status = 'active' and x.chip <> 'virtual';
  get diagnostics n = row_count;
  if n = 0 then return jsonb_build_object('error', 'not_active'); end if;
  perform public.net__audit('admin_unbind_card', p_card_id::text, null);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.net_admin_revoke_card(p_card_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare n int;
begin
  perform public.net__require_staff();
  update public.net_cards x set status = 'revoked', revoked_at = now() where x.id = p_card_id and x.status <> 'revoked';
  get diagnostics n = row_count;
  if n = 0 then return jsonb_build_object('error', 'already_revoked'); end if;
  perform public.net__audit('admin_revoke_card', p_card_id::text, null);
  return jsonb_build_object('ok', true);
end $$;

-- Lost card: old token deactivates at once, spare binds (K-27, T17).
create or replace function public.net_admin_swap_lost_card(p_user uuid, p_new_code text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  old_ids uuid[];
  res jsonb;
begin
  perform public.net__require_staff();
  select array_agg(x.id) into old_ids from public.net_cards x where x.user_id = p_user and x.status = 'active';
  update public.net_cards x set status = 'revoked', revoked_at = now() where x.id = any(coalesce(old_ids, '{}'));
  res := public.net_admin_bind_card(p_user, p_new_code);
  if res ? 'error' then raise exception 'net:%', res ->> 'error' using errcode = 'P0001'; end if;
  perform public.net__audit('admin_swap_lost_card', p_user::text, jsonb_build_object('revoked', old_ids, 'new_code', p_new_code));
  return res || jsonb_build_object('revoked', to_jsonb(coalesce(old_ids, '{}')));
exception when raise_exception then
  return jsonb_build_object('error', replace(sqlerrm, 'net:', ''));
end $$;

create or replace function public.net_admin_list_cards(p_status text default null, p_batch text default null,
                                                       p_limit int default 500, p_offset int default 0)
returns jsonb language plpgsql security definer set search_path = '' as $$
begin
  perform public.net__require_staff();
  return jsonb_build_object(
    'cards', coalesce((select jsonb_agg(public.net__card_json(c) order by c.batch, c.printed_code) from (
       select * from public.net_cards x
        where (p_status is null or x.status = p_status) and (p_batch is null or x.batch = p_batch)
        order by x.batch, x.printed_code
        limit least(greatest(coalesce(p_limit, 500), 1), 5000) offset greatest(coalesce(p_offset, 0), 0)) c), '[]'::jsonb),
    'batches', coalesce((select jsonb_agg(jsonb_build_object('batch', b.batch, 'unbound', b.u, 'active', b.a, 'revoked', b.r) order by b.batch)
       from (select x.batch, count(*) filter (where x.status = 'unbound') u, count(*) filter (where x.status = 'active') a,
                    count(*) filter (where x.status = 'revoked') r
             from public.net_cards x group by x.batch) b), '[]'::jsonb));
end $$;

-- Import from tools/card-manifest out/import.json: [{token_hash: hex(64), printed_code, chip, batch}].
create or replace function public.net_admin_import_cards(p_rows jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  inserted int;
  total int := jsonb_array_length(coalesce(p_rows, '[]'));
begin
  perform public.net__require_staff();
  insert into public.net_cards (token_hash, printed_code, chip, batch)
  select decode(r ->> 'token_hash', 'hex'), upper(r ->> 'printed_code'), coalesce(r ->> 'chip', 'ntag213'), r ->> 'batch'
  from jsonb_array_elements(p_rows) r
  where (r ->> 'token_hash') ~ '^[0-9a-f]{64}$'
  on conflict do nothing;
  get diagnostics inserted = row_count;
  perform public.net__audit('admin_import_cards', null, jsonb_build_object('inserted', inserted, 'total', total));
  return jsonb_build_object('inserted', inserted, 'skipped', total - inserted);
end $$;

create or replace function public.net_admin_list_reports(p_status text default 'open')
returns jsonb language plpgsql security definer set search_path = '' as $$
begin
  perform public.net__require_staff();
  return jsonb_build_object('reports', coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', r.id, 'reason', r.reason, 'note', r.note, 'status', r.status, 'resolution', r.resolution,
      'created_at', r.created_at,
      'reporter', jsonb_build_object('id', r.reporter, 'name', (select p.display_name from public.net_people p where p.user_id = r.reporter limit 1)),
      'reported', jsonb_build_object('id', r.reported, 'name', (select p.display_name from public.net_people p where p.user_id = r.reported limit 1)),
      'reports_against', (select count(*) from public.net_reports r2 where r2.reported = r.reported)) order by r.created_at desc)
    from public.net_reports r where p_status is null or r.status = p_status), '[]'::jsonb));
end $$;

create or replace function public.net_admin_resolve_report(p_id uuid, p_resolution text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid := public.net__require_staff(); n int;
begin
  update public.net_reports r set status = 'resolved', resolution = left(p_resolution, 500), resolved_by = actor, resolved_at = now()
   where r.id = p_id and r.status = 'open';
  get diagnostics n = row_count;
  if n = 0 then return jsonb_build_object('error', 'not_open'); end if;
  perform public.net__audit('admin_resolve_report', p_id::text, jsonb_build_object('resolution', p_resolution));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.net_admin_metrics()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare registered int; completed int;
begin
  perform public.net__require_staff();
  select count(*) into registered from public.net_people p where p.is_registered;
  select count(*) into completed from public.net_people p
   where exists (select 1 from public.net_profile_themes t where t.user_id = p.user_id)
     and exists (select 1 from public.net_profile_ext e where e.user_id = p.user_id and e.headline is not null);
  return jsonb_build_object(
    'as_of', now(),
    'taps_total', (select count(*) from public.net_tap_events t where t.kind = 'profile'),
    'taps_last_hour', (select count(*) from public.net_tap_events t where t.kind = 'profile' and t.at > now() - interval '1 hour'),
    'connections', (select count(*) from public.net_connections c where c.removed_at is null),
    'connections_today', (select count(*) from public.net_connections c where c.removed_at is null and c.created_at > date_trunc('day', now())),
    'activations', (select count(*) from public.net_cards c where c.status = 'active' and c.chip <> 'virtual'),
    'digital_passes', (select count(*) from public.net_cards c where c.status = 'active' and c.chip = 'virtual'),
    'cards_unbound', (select count(*) from public.net_cards c where c.status = 'unbound'),
    'registered', registered,
    'profiles_completed', completed,
    'completion_rate', case when registered = 0 then 0 else round(completed::numeric / registered, 3) end,
    'map_opens', (select count(*) from public.net_metric_events m where m.kind = 'map_open'),
    'overlap_opens', (select count(*) from public.net_metric_events m where m.kind = 'overlap_open'),
    'client_errors', (select count(*) from public.net_metric_events m where m.kind = 'client_error'),
    'rate_limited', (select count(*) from public.net_tap_events t where t.result = 'limited'),
    'reports_open', (select count(*) from public.net_reports r where r.status = 'open'),
    'flags', public.net_get_feature_flags()
  );
end $$;

create or replace function public.net_admin_set_flag(p_key text, p_enabled boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
begin
  perform public.net__require_staff();
  if not public.net_is_admin() then raise exception 'net:forbidden' using errcode = 'P0001'; end if;
  if p_key not in ('tap', 'map', 'overlap', 'galaxy', 'digital_pass') then return jsonb_build_object('error', 'bad_key'); end if;
  insert into public.net_feature_flags (key, enabled) values (p_key, p_enabled)
  on conflict (key) do update set enabled = excluded.enabled;
  perform public.net__audit('admin_set_flag', p_key, jsonb_build_object('enabled', p_enabled));
  return public.net_get_feature_flags();
end $$;

-- K-83: people who asked for a follow-up reminder; organisers email them on 30 Nov.
create or replace function public.net_admin_export_reminders()
returns jsonb language plpgsql security definer set search_path = '' as $$
begin
  perform public.net__require_staff();
  perform public.net__audit('admin_export_reminders', null, null);
  return jsonb_build_object('people', coalesce((
    select jsonb_agg(jsonb_build_object('name', p.display_name, 'email', p.email,
             'connections', (select count(*) from public.net__direct_ids(p.user_id))) order by p.display_name)
    from public.net_profile_ext e join public.net_people p on p.user_id = e.user_id
    where e.followup_reminder), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------- jobs (not client-callable)

create or replace function public.net_prune()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare n1 int; n2 int;
begin
  delete from public.net_tap_events t where t.at < now() - interval '30 days';
  get diagnostics n1 = row_count;
  delete from public.net_metric_events m where m.at < now() - interval '90 days';
  get diagnostics n2 = row_count;
  return jsonb_build_object('tap_events', n1, 'metric_events', n2);
end $$;

-- 29 Dec 2026 retention (PRD 6.4). Dry run by default; a real run before the date needs p_force.
create or replace function public.net_retention_delete(p_dry_run boolean default true, p_force boolean default false)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare counts jsonb;
begin
  counts := jsonb_build_object(
    'connections', (select count(*) from public.net_connections),
    'meetings', (select count(*) from public.net_meetings),
    'contact_grants', (select count(*) from public.net_contact_grants),
    'person_notes', (select count(*) from public.net_person_notes),
    'tap_events', (select count(*) from public.net_tap_events),
    'similarity_edges', (select count(*) from public.net_similarity_edges),
    'consents', (select count(*) from public.net_consents),
    'blocks', (select count(*) from public.net_blocks),
    'reports', (select count(*) from public.net_reports),
    'profile_ext', (select count(*) from public.net_profile_ext),
    'profile_themes', (select count(*) from public.net_profile_themes),
    'metric_events', (select count(*) from public.net_metric_events),
    'cards_bound', (select count(*) from public.net_cards c where c.user_id is not null));
  if p_dry_run then return jsonb_build_object('dry_run', true, 'would_delete', counts); end if;
  if now() < '2026-12-29'::timestamptz and not p_force then
    return jsonb_build_object('error', 'before_retention_date', 'would_delete', counts);
  end if;

  insert into public.net_aggregates (key, value)
  select k, (counts ->> k)::bigint from jsonb_object_keys(counts) k;

  perform set_config('net.allow_consent_delete', 'on', true);
  delete from public.net_connections;
  delete from public.net_meetings;
  delete from public.net_contact_grants;
  delete from public.net_person_notes;
  delete from public.net_tap_events;
  delete from public.net_similarity_edges;
  delete from public.net_consents;
  delete from public.net_blocks;
  delete from public.net_reports;
  delete from public.net_profile_themes;
  delete from public.net_profile_ext;
  delete from public.net_metric_events;
  update public.net_cards set status = 'revoked', user_id = null, revoked_at = coalesce(revoked_at, now())
   where user_id is not null;
  perform set_config('net.allow_consent_delete', 'off', true);
  insert into public.net_audit (actor, action, detail) values (null, 'retention_delete', counts);
  return jsonb_build_object('dry_run', false, 'deleted', counts);
end $$;

-- ===== supabase/migrations/20261114000500_network_grants.sql
-- pan-iim-network: grants (K-63). Runs last.
-- 1. No direct table, view or sequence access for anon or authenticated (Supabase grants them by default).
-- 2. No function is executable unless listed below. anon may call only net_resolve_token.

do $$
declare r record;
begin
  for r in select c.relname, c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
           where n.nspname = 'public' and c.relname like 'net\_%' and c.relkind in ('r', 'v', 'S', 'm')
  loop
    execute format('revoke all on %s public.%I from public, anon, authenticated',
                   case when r.relkind = 'S' then 'sequence' else 'table' end, r.relname);
  end loop;

  for r in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname like 'net\_%'
  loop
    execute format('revoke all on function %s from public, anon, authenticated', r.sig);
  end loop;
end $$;

do $$
declare
  fn text;
  client_fns text[] := array[
    'net_get_feature_flags', 'net_list_themes', 'net_resolve_token',
    'net_get_profile_by_token', 'net_connect_via_card', 'net_undo_connection', 'net_record_meeting',
    'net_activate_card', 'net_report_lost_card', 'net_get_my_pass', 'net_issue_digital_pass',
    'net_get_my_settings', 'net_set_consent', 'net_update_profile_ext', 'net_withdraw_all',
    'net_grant_contact', 'net_revoke_contact', 'net_get_profile_detail', 'net_set_note',
    'net_remove_connection', 'net_list_connections', 'net_block_user', 'net_unblock_user', 'net_report_user',
    'net_log_event', 'net_get_ego_graph', 'net_get_my_network_summary', 'net_venn_counts', 'net_list_region',
    'net_search_people', 'net_suggest_people',
    'net_admin_whoami', 'net_admin_find_delegate', 'net_admin_bind_card', 'net_admin_unbind_card',
    'net_admin_revoke_card', 'net_admin_swap_lost_card', 'net_admin_list_cards', 'net_admin_import_cards',
    'net_admin_list_reports', 'net_admin_resolve_report', 'net_admin_metrics', 'net_admin_set_flag',
    'net_admin_export_reminders'
  ];
begin
  foreach fn in array client_fns loop
    execute format('grant execute on function public.%I to authenticated', fn);
  end loop;
  execute 'grant execute on function public.net_resolve_token to anon';
end $$;

insert into public.net_schema_version (version) values (1) on conflict (version) do nothing;
